namespace Charker;
internal static class CuktechDiagnostic {
 public static int Run(string output){var log=new List<string>();var clock=System.Diagnostics.Stopwatch.StartNew();using var link=new CuktechBluetooth();void Trace(string text){lock(log){if(log.Count<20000)log.Add($"{clock.Elapsed.TotalSeconds:F3}s {text}");}}link.Trace+=Trace;link.Error+=e=>Trace("错误："+e);Exception? failure=null;int samples=0;int seconds=int.TryParse(Environment.GetEnvironmentVariable("ANKER_CUKTECH_DIAGNOSTIC_SECONDS"),out var requested)?Math.Clamp(requested,20,600):20;
  try{var prefs=Store.Read<Preferences>("settings.json")??throw new IOException("找不到已保存配置");var saved=prefs.Devices.LastOrDefault(d=>d.Model==CuktechProtocol.Model)??throw new IOException("没有已保存的酷态科");string mac=saved.HardwareAddress??CuktechProtocol.Mac(ulong.Parse(saved.Id));var token=new CuktechSecrets().Get(mac)??throw new IOException("未找到已导入的酷态科 Token");Trace("已读取本机加密凭据；不记录设备身份或凭据内容");link.Connect(ulong.Parse(saved.Id),token).WaitAsync(TimeSpan.FromSeconds(95)).GetAwaiter().GetResult();Trace("蓝牙认证及初始数据读取成功");DateTimeOffset? last=null;for(int i=0;i<seconds;i++){Thread.Sleep(1000);if(!link.State.Connected||link.State.Stale)throw new IOException("连续读取期间设备断连或数据过期");if(link.State.Updated!=last){last=link.State.Updated;samples++;}if((i+1)%10==0){string progress=Path.ChangeExtension(Path.GetFullPath(output),"progress.json");File.WriteAllText(progress+".tmp",JsonSerializer.Serialize(new{observedSeconds=i+1,requestedSeconds=seconds,samples,connected=link.State.Connected,phase=link.Phase}));File.Move(progress+".tmp",progress,true);}}if(samples<8)throw new IOException("收到的新采样不足");Trace($"连续 {seconds} 秒读取检查：{samples} 次独立新采样");}
  catch(Exception e){failure=e;Trace("诊断结束："+e.GetType().Name+"："+e.Message);}finally{var result=new{at=DateTimeOffset.Now,success=failure==null&&samples>=8,phase=link.Phase,exception=failure?.GetType().Name,message=failure?.Message,samples,observationSeconds=seconds,elapsedSeconds=clock.Elapsed.TotalSeconds,connected=link.State.Connected,firmware=link.State.Firmware,events=log.ToArray()};File.WriteAllText(Path.GetFullPath(output),JsonSerializer.Serialize(result,new JsonSerializerOptions{WriteIndented=true,Encoder=System.Text.Encodings.Web.JavaScriptEncoder.UnsafeRelaxedJsonEscaping}));}return failure==null?0:1;
 }
}
